-- ================================================================
-- atena_crm_v4.sql
-- پورتال فروش آتنا زیست درمان — نسخه اصلاح‌شده
-- تغییرات نسبت به v3:
--   • باگ CRITICAL: sessions.expires_at default اصلاح شد
--   • باگ CRITICAL: جدول province_centers اضافه شد
--   • باگ CRITICAL: owner duplication حذف از record_edits
--   • باگ HIGH: followup_date به BIGINT تبدیل شد
--   • باگ HIGH: province_id به centers اضافه شد
--   • باگ HIGH: audit_trail unique constraint اصلاح شد
--   • باگ MEDIUM: last_activity default اصلاح شد
--   • باگ MEDIUM: sync_log با last_record_ts کامل شد
--   • باگ MEDIUM: monthly_targets با target_type کامل شد
--   • بهبود: biopsy_pct و weight به DECIMAL
--   • بهبود: ایندکس‌های لازم اضافه شد
--   • بهبود: checklist.items به JSON
-- ================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET time_zone = '+03:30';

-- ── جداول ─────────────────────────────────────────────────────

-- ----------------------------------------------------------------
-- users
-- ----------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `users` (
  `username`       VARCHAR(100) NOT NULL,
  `display_name`   VARCHAR(100) NOT NULL DEFAULT '',
  `role`           VARCHAR(100) NOT NULL DEFAULT '',
  `password_hash`  VARCHAR(64)  NOT NULL,
  `is_manager`     TINYINT(1)   NOT NULL DEFAULT 0,
  `is_super_admin` TINYINT(1)   NOT NULL DEFAULT 0,
  `is_inactive`    TINYINT(1)   NOT NULL DEFAULT 0,
  `created_at`     TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`username`),
  KEY `idx_active` (`is_inactive`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------------------------------------------
-- sessions
-- BUG FIX: expires_at دیگر DEFAULT CURRENT_TIMESTAMP نیست.
-- PHP هنگام INSERT باید NOW() + INTERVAL 12 HOUR بدهد.
-- ----------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `sessions` (
  `token`      VARCHAR(64)  NOT NULL,
  `username`   VARCHAR(100) NOT NULL,
  `expires_at` TIMESTAMP    NOT NULL,             -- ← FIX: no default
  `created_at` TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`token`),
  KEY `idx_user`   (`username`),
  KEY `idx_exp`    (`expires_at`),
  KEY `idx_user_exp` (`username`, `expires_at`)   -- برای cleanup سریع
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------------------------------------------
-- provinces
-- ----------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `provinces` (
  `id`         VARCHAR(20)   NOT NULL,
  `row_num`    INT           NOT NULL DEFAULT 0,
  `name`       VARCHAR(100)  NOT NULL DEFAULT '',
  `potential`  TINYINT       NOT NULL DEFAULT 3,
  `biopsy_pct` DECIMAL(6,4)  NOT NULL DEFAULT 0,  -- ← FIX: از VARCHAR به DECIMAL
  `owner`      VARCHAR(100)           DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_owner`  (`owner`),                      -- ← NEW INDEX
  KEY `idx_rownum` (`row_num`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------------------------------------------
-- centers (مراکز تهران)
-- BUG FIX: province_id اضافه شد (برای تهران = 'tehran')
-- ----------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `centers` (
  `id`          VARCHAR(20)   NOT NULL,
  `province_id` VARCHAR(20)   NOT NULL DEFAULT 'tehran',  -- ← NEW
  `row_num`     INT           NOT NULL DEFAULT 0,
  `name`        VARCHAR(200)  NOT NULL DEFAULT '',
  `potential`   TINYINT       NOT NULL DEFAULT 3,
  `center_type` VARCHAR(100)  NOT NULL DEFAULT '',
  `lead_type`   VARCHAR(50)   NOT NULL DEFAULT 'سرنخ',
  `weight`      DECIMAL(6,4)  NOT NULL DEFAULT 0,          -- ← FIX: از VARCHAR به DECIMAL
  `owner`       VARCHAR(100)           DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_owner`      (`owner`),                          -- ← NEW INDEX
  KEY `idx_province`   (`province_id`),
  KEY `idx_rownum`     (`row_num`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------------------------------------------
-- province_centers (مراکز استانی)
-- NEW TABLE: قبلاً فقط در JS بود — حالا در DB ذخیره می‌شود
-- ----------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `province_centers` (
  `id`          VARCHAR(50)   NOT NULL,   -- فرمت: pc_{province_id}_{row}
  `province_id` VARCHAR(20)   NOT NULL,
  `row_num`     INT           NOT NULL DEFAULT 0,
  `name`        VARCHAR(200)  NOT NULL DEFAULT '',
  `potential`   TINYINT       NOT NULL DEFAULT 3,
  `center_type` VARCHAR(100)  NOT NULL DEFAULT '',
  `lead_type`   VARCHAR(50)   NOT NULL DEFAULT 'سرنخ',
  `owner`       VARCHAR(100)           DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_province`   (`province_id`),
  KEY `idx_owner`      (`owner`),
  KEY `idx_rownum`     (`province_id`, `row_num`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------------------------------------------
-- record_edits
-- BUG FIX:
--   • owner حذف شد (در base table هست، cascade از آنجا)
--   • followup_date از VARCHAR به BIGINT (unix ms)
--   • last_activity default به UNIX_TIMESTAMP()*1000
--   • province_type status جداست از center status
-- ----------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `record_edits` (
  `record_type`   VARCHAR(20)  NOT NULL DEFAULT '',
  `record_id`     VARCHAR(255) NOT NULL DEFAULT '',
  `status`        VARCHAR(50)           DEFAULT NULL,        -- ← NULL برای province
  `lead_type`     VARCHAR(50)  NOT NULL DEFAULT 'ندارد',
  `potential`     TINYINT      NOT NULL DEFAULT 3,
  `center_type`   VARCHAR(100) NOT NULL DEFAULT '',
  `followup_date` BIGINT                DEFAULT NULL,        -- ← FIX: BIGINT unix-ms
  `followup_text` VARCHAR(30)           DEFAULT NULL,        -- جلالی نمایش (read-only cache)
  `products`      JSON                  DEFAULT NULL,        -- ← FIX: JSON type
  `last_activity` BIGINT       NOT NULL DEFAULT 0,
  `updated_at`    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`record_type`, `record_id`),                  -- ← FIX: composite PK (نه AUTO_INCREMENT)
  KEY `idx_followup`  (`followup_date`),
  KEY `idx_status`    (`status`),
  KEY `idx_lead`      (`lead_type`),
  KEY `idx_updated`   (`updated_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------------------------------------------
-- center_owners  (جدول جداگانه برای owner — single source of truth)
-- BUG FIX: owner در base table (provinces/centers) و record_edits
--          duplication داشت. حالا owner در یک جدول مستقل است.
-- ----------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `record_owners` (
  `record_type` VARCHAR(20)  NOT NULL,
  `record_id`   VARCHAR(255) NOT NULL,
  `owner`       VARCHAR(100)          DEFAULT NULL,
  `updated_at`  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`record_type`, `record_id`),
  KEY `idx_owner`   (`owner`),
  KEY `idx_updated` (`updated_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------------------------------------------
-- notes
-- ----------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `notes` (
  `id`              BIGINT       NOT NULL AUTO_INCREMENT,
  `record_type`     VARCHAR(20)  NOT NULL DEFAULT '',
  `record_id`       VARCHAR(255) NOT NULL DEFAULT '',
  `note_text`       TEXT         NOT NULL,
  `jalali_datetime` VARCHAR(30)  NOT NULL DEFAULT '',
  `raw_ts`          BIGINT       NOT NULL DEFAULT 0,
  `created_by`      VARCHAR(100)          DEFAULT NULL,
  PRIMARY KEY (`id`),
  -- BUG FIX: raw_ts تنها unique نبود — با uuid بهتر بود ولی برای سازگاری:
  UNIQUE KEY `uq_note` (`record_type`, `record_id`, `raw_ts`, `created_by`),
  KEY `idx_record`  (`record_type`, `record_id`),
  KEY `idx_ts`      (`raw_ts`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------------------------------------------
-- audit_trail
-- BUG FIX: UNIQUE constraint اجازه دو تغییر همزمان نمی‌داد
--          حذف UNIQUE، به جایش composite index
-- ----------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `audit_trail` (
  `id`          BIGINT       NOT NULL AUTO_INCREMENT,
  `record_type` VARCHAR(20)  NOT NULL DEFAULT '',
  `record_id`   VARCHAR(255) NOT NULL DEFAULT '',
  `field_name`  VARCHAR(50)  NOT NULL DEFAULT '',
  `old_value`   VARCHAR(500) NOT NULL DEFAULT '',  -- ← افزایش از 255 به 500
  `new_value`   VARCHAR(500) NOT NULL DEFAULT '',
  `changed_by`  VARCHAR(100)          DEFAULT NULL,
  `changed_at`  BIGINT       NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  -- ← FIX: UNIQUE حذف شد، index جایگزین
  KEY `idx_record`  (`record_type`, `record_id`),
  KEY `idx_field`   (`record_type`, `record_id`, `field_name`),
  KEY `idx_by`      (`changed_by`),
  KEY `idx_at`      (`changed_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------------------------------------------
-- checklist
-- ----------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `checklist` (
  `check_date` VARCHAR(12)  NOT NULL DEFAULT '',
  `username`   VARCHAR(100) NOT NULL DEFAULT '',
  `items`      JSON                  DEFAULT NULL,  -- ← FIX: JSON type
  `daily_note` TEXT                  DEFAULT NULL,
  `score`      TINYINT      NOT NULL DEFAULT 0,     -- ← NEW: امتیاز روز (محاسبه‌شده)
  `updated_at` TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`check_date`, `username`)             -- ← FIX: composite PK بدون AUTO_INCREMENT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------------------------------------------
-- monthly_targets
-- BUG FIX: target_type اضافه شد
-- ----------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `monthly_targets` (
  `username`        VARCHAR(100) NOT NULL DEFAULT '',
  `year_month`      VARCHAR(8)   NOT NULL DEFAULT '',
  `target_type`     VARCHAR(20)  NOT NULL DEFAULT 'overall',  -- ← NEW: overall|province|center
  `entry_target`    INT          NOT NULL DEFAULT 0,
  `lead_opp_target` INT          NOT NULL DEFAULT 0,
  `contract_target` INT          NOT NULL DEFAULT 0,
  `revenue_target`  BIGINT       NOT NULL DEFAULT 0,          -- ← NEW: تارگت درآمد (ریال)
  PRIMARY KEY (`username`, `year_month`, `target_type`)        -- ← FIX: composite PK
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------------------------------------------
-- sync_log
-- BUG FIX: last_record_ts اضافه شد برای incremental sync
-- ----------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `sync_log` (
  `username`       VARCHAR(100) NOT NULL,
  `last_push`      TIMESTAMP    NULL DEFAULT NULL,
  `last_pull`      TIMESTAMP    NULL DEFAULT NULL,
  `last_record_ts` BIGINT       NOT NULL DEFAULT 0,  -- ← NEW: آخرین updated_at sync شده
  `push_count`     INT          NOT NULL DEFAULT 0,  -- ← NEW: آمار
  `pull_count`     INT          NOT NULL DEFAULT 0,
  PRIMARY KEY (`username`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;

-- ================================================================
-- Migration از v3 به v4 (اگر جداول قبلاً موجود باشند)
-- ================================================================

-- sessions: حذف default از expires_at
ALTER TABLE `sessions`
  MODIFY COLUMN `expires_at` TIMESTAMP NOT NULL;

-- provinces: biopsy_pct به DECIMAL
ALTER TABLE `provinces`
  MODIFY COLUMN `biopsy_pct` DECIMAL(6,4) NOT NULL DEFAULT 0,
  ADD INDEX IF NOT EXISTS `idx_owner` (`owner`);

-- centers: اضافه کردن province_id + ایندکس‌ها
ALTER TABLE `centers`
  ADD COLUMN IF NOT EXISTS `province_id` VARCHAR(20) NOT NULL DEFAULT 'tehran' AFTER `id`,
  MODIFY COLUMN `weight` DECIMAL(6,4) NOT NULL DEFAULT 0,
  ADD INDEX IF NOT EXISTS `idx_owner`    (`owner`),
  ADD INDEX IF NOT EXISTS `idx_province` (`province_id`);

-- record_edits: اصلاح followup_date + حذف AUTO_INCREMENT
-- ⚠ این migration داده‌های followup_date را تبدیل می‌کند
ALTER TABLE `record_edits`
  MODIFY COLUMN `followup_date` BIGINT DEFAULT NULL,
  ADD COLUMN IF NOT EXISTS `followup_text` VARCHAR(30) DEFAULT NULL AFTER `followup_date`,
  ADD COLUMN IF NOT EXISTS `products_json` JSON DEFAULT NULL,
  ADD INDEX IF NOT EXISTS `idx_lead`    (`lead_type`),
  ADD INDEX IF NOT EXISTS `idx_updated` (`updated_at`);

-- audit_trail: حذف UNIQUE constraint مشکل‌ساز
ALTER TABLE `audit_trail`
  DROP INDEX IF EXISTS `uq_audit`,
  MODIFY COLUMN `old_value` VARCHAR(500) NOT NULL DEFAULT '',
  MODIFY COLUMN `new_value` VARCHAR(500) NOT NULL DEFAULT '';

-- checklist: تبدیل items به JSON + اضافه score
ALTER TABLE `checklist`
  ADD COLUMN IF NOT EXISTS `score` TINYINT NOT NULL DEFAULT 0 AFTER `daily_note`;

-- sync_log: اضافه کردن فیلدهای جدید
ALTER TABLE `sync_log`
  ADD COLUMN IF NOT EXISTS `last_record_ts` BIGINT NOT NULL DEFAULT 0 AFTER `last_pull`,
  ADD COLUMN IF NOT EXISTS `push_count`     INT    NOT NULL DEFAULT 0 AFTER `last_record_ts`,
  ADD COLUMN IF NOT EXISTS `pull_count`     INT    NOT NULL DEFAULT 0 AFTER `push_count`;

-- monthly_targets: اضافه کردن target_type و revenue_target
ALTER TABLE `monthly_targets`
  ADD COLUMN IF NOT EXISTS `target_type`    VARCHAR(20) NOT NULL DEFAULT 'overall' AFTER `year_month`,
  ADD COLUMN IF NOT EXISTS `revenue_target` BIGINT      NOT NULL DEFAULT 0;

-- ================================================================
-- داده‌های اولیه
-- ================================================================


-- ════════════════════════════════════════════════════════════════
-- جدول tags — برچسب‌ها با تاریخ انقضای اختیاری
-- ════════════════════════════════════════════════════════════════
CREATE TABLE IF NOT EXISTS `tags` (
  `id`           INT NOT NULL AUTO_INCREMENT,
  `name`         VARCHAR(50) NOT NULL,
  `color`        VARCHAR(7)  NOT NULL DEFAULT '#3b82f6',
  `expires_at`   VARCHAR(10) DEFAULT NULL,
  `description`  VARCHAR(200) DEFAULT NULL,
  `created_by`   VARCHAR(100) NOT NULL,
  `created_at`   TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_tag_name` (`name`),
  KEY `idx_expires` (`expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ════════════════════════════════════════════════════════════════
-- جدول record_tags — اتصال many-to-many بین record و tag
-- ════════════════════════════════════════════════════════════════
CREATE TABLE IF NOT EXISTS `record_tags` (
  `record_type`  VARCHAR(20)  NOT NULL,
  `record_id`    VARCHAR(255) NOT NULL,
  `tag_id`       INT          NOT NULL,
  `assigned_by`  VARCHAR(100),
  `assigned_at`  TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`record_type`, `record_id`, `tag_id`),
  KEY `idx_tag` (`tag_id`),
  KEY `idx_record` (`record_type`, `record_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ════════════════════════════════════════════════════════════════
-- جدول events — رویدادها، قرارها، برنامه‌ریزی شخصی
-- ════════════════════════════════════════════════════════════════
CREATE TABLE IF NOT EXISTS `events` (
  `id`                  INT NOT NULL AUTO_INCREMENT,
  `title`               VARCHAR(200) NOT NULL,
  `description`         TEXT,
  `start_at`            BIGINT NOT NULL COMMENT 'unix ms',
  `end_at`              BIGINT,
  `all_day`             TINYINT(1) NOT NULL DEFAULT 0,
  `color`               VARCHAR(7) DEFAULT '#0ea5e9',
  `owner`               VARCHAR(100) NOT NULL,
  `related_record_type` VARCHAR(20),
  `related_record_id`   VARCHAR(255),
  `reminder_minutes`    INT DEFAULT 0 COMMENT '0=none, 15, 60, 1440',
  `shared_with_team`    TINYINT(1) NOT NULL DEFAULT 0,
  `recurrence`          VARCHAR(20) DEFAULT NULL COMMENT 'daily|weekly|monthly',
  `status`              VARCHAR(20) DEFAULT 'planned' COMMENT 'planned|done|cancelled',
  `created_at`          TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  `updated_at`          TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_owner_time` (`owner`, `start_at`),
  KEY `idx_related` (`related_record_type`, `related_record_id`),
  KEY `idx_time` (`start_at`),
  KEY `idx_shared` (`shared_with_team`, `start_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ════════════════════════════════════════════════════════════════
-- جدول user_preferences — تنظیمات کاربر (view، theme، ...)
-- ════════════════════════════════════════════════════════════════
CREATE TABLE IF NOT EXISTS `user_preferences` (
  `username`    VARCHAR(100) NOT NULL,
  `pref_key`    VARCHAR(50)  NOT NULL,
  `pref_value`  TEXT,
  `updated_at`  TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`username`, `pref_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

