-- اطمینان از province_id='tehran' برای مراکز تهران
UPDATE `centers` SET `province_id`='tehran' WHERE `province_id`='' OR `province_id` IS NULL;

-- ================================================================
-- VIEW: نمای یکپارچه مرکز + ویرایش‌ها (بدون JOIN پیچیده در PHP)
-- ================================================================
CREATE OR REPLACE VIEW `v_centers_full` AS
  SELECT
    c.id,
    c.province_id,
    c.row_num,
    c.name,
    COALESCE(re.potential,  c.potential)    AS potential,
    COALESCE(re.center_type, c.center_type) AS center_type,
    COALESCE(re.lead_type,  c.lead_type)    AS lead_type,
    COALESCE(ro.owner,      c.owner)        AS owner,
    COALESCE(re.status,    'بدون تماس')    AS status,
    re.followup_date,
    re.followup_text,
    re.products,
    re.last_activity,
    re.updated_at
  FROM `centers` c
  LEFT JOIN `record_edits` re  ON re.record_type = 'center' AND re.record_id = c.id
  LEFT JOIN `record_owners` ro ON ro.record_type = 'center' AND ro.record_id = c.id;

CREATE OR REPLACE VIEW `v_provinces_full` AS
  SELECT
    p.id,
    p.row_num,
    p.name,
    COALESCE(re.potential, p.potential)  AS potential,
    p.biopsy_pct,
    COALESCE(ro.owner,     p.owner)      AS owner,
    COALESCE(re.status,    NULL)         AS status,      -- province status = NULL اگر تنظیم نشده
    re.followup_date,
    re.followup_text,
    re.last_activity,
    re.updated_at
  FROM `provinces` p
  LEFT JOIN `record_edits` re  ON re.record_type = 'province' AND re.record_id = p.id
  LEFT JOIN `record_owners` ro ON ro.record_type = 'province' AND ro.record_id = p.id;

CREATE OR REPLACE VIEW `v_province_centers_full` AS
  SELECT
    pc.id,
    pc.province_id,
    pc.row_num,
    pc.name,
    COALESCE(re.potential,   pc.potential)   AS potential,
    COALESCE(re.center_type, pc.center_type) AS center_type,
    COALESCE(re.lead_type,   pc.lead_type)   AS lead_type,
    COALESCE(ro.owner,       pc.owner)       AS owner,
    COALESCE(re.status,     'بدون تماس')    AS status,
    re.followup_date,
    re.followup_text,
    re.products,
    re.last_activity,
    re.updated_at
  FROM `province_centers` pc
  LEFT JOIN `record_edits` re  ON re.record_type = 'pc' AND re.record_id = pc.id
  LEFT JOIN `record_owners` ro ON ro.record_type = 'pc' AND ro.record_id = pc.id;

-- ================================================================
-- STORED PROCEDURE: ذخیره یک ویرایش (SaveQueue endpoint)
-- جایگزین ON DUPLICATE KEY UPDATE پراکنده در PHP
-- ================================================================
-- Stored Procedures حذف شدند (در هاست اشتراکی پشتیبانی نمی‌شوند)
-- از pull.php و push.php برای همین کار استفاده می‌شود

-- ================================================================
-- ایندکس‌های ترکیبی بهینه برای کوئری‌های رایج
-- ================================================================
-- "مراکز یک استان با وضعیت خاص"
CREATE INDEX IF NOT EXISTS `idx_re_type_status`
  ON `record_edits`(`record_type`, `status`);

-- "مراکز یک مسئول با followup امروز"
CREATE INDEX IF NOT EXISTS `idx_re_followup_active`
  ON `record_edits`(`followup_date`, `record_type`);

-- ================================================================
-- Cleanup jobs (اجرا دستی هفتگی یا با event scheduler)
-- ================================================================
-- حذف session های منقضی:
-- DELETE FROM sessions WHERE expires_at < NOW();

-- حذف audit trail قدیمی‌تر از ۲ سال:
-- DELETE FROM audit_trail WHERE changed_at < (UNIX_TIMESTAMP(NOW() - INTERVAL 2 YEAR)*1000);


-- اضافه‌کردن icon به tags (idempotent)
ALTER TABLE `tags` ADD COLUMN IF NOT EXISTS `icon` VARCHAR(10) DEFAULT NULL AFTER `color`;
